+      }));
+
+  // Act
+  prefetcher_->Prefetch();
+  std::optional<NewTabPageAdInfo> result = prefetcher_->MaybeGetPrefetchedAd();
+
+  // Assert
+  EXPECT_FALSE(result.has_value());

