    return this.getPartialContentWithSelector(fromMeta, toMeta, keySelector)
  }

  private getPartialContentWithKey(
    fromMeta: XmlContent[],
    toMeta: XmlContent[],
    keyField: string
  ): XmlContent[] {
    const keySelector = (item: XmlContent[0]) => item[keyField]
    const fromMap = new Map(fromMeta.map(item => [keySelector(item), item]))
    return this.getPartialContentWithSelector(fromMeta, toMeta, keySelector)
  }

  private getPartialContentWithSelector(
    fromMeta: XmlContent[],
    toMeta: XmlContent[],
    keySelector: (item: XmlContent[0]) => string
  ): XmlContent[] {
    const fromSet = new Set<string>(fromMeta.map(keySelector))
    const diff = toMeta.filter(item => !fromSet.has(keySelector(item)))

    if (!isEmpty(diff)) {
      this.isEmpty = false
    }

    return diff
  }
