+    const posMint = new Map<Cardano.AssetId, bigint>();
+    const negMint = new Map<Cardano.AssetId, bigint>();
+
+    for (const [id, q] of mint) (q > 0n ? posMint : negMint).set(id, q > 0n ? q : -q);
