+          : true) &&
+          (p.validUntil
+            ? new Date(new Date().setHours(0, 0, 0, 0)) <= new Date(new Date(p.validUntil).setHours(0, 0, 0, 0))
+            : true));
+
+      return matchesName && matchesActive;
+    });
+
+    setFilteredPositionNames(applyDefaultSorting(filtered));
+    setPage(0);
