+TEST_F(BraveAdsNewTabPageAdPrefetcherTest, NoAdWithoutPrefetch) {
+  // Arrange & Act
+  std::optional<NewTabPageAdInfo> result = prefetcher_->MaybeGetPrefetchedAd();
+
+  // Assert
+  EXPECT_FALSE(result.has_value());
+}
+
+TEST_F(BraveAdsNewTabPageAdPrefetcherTest, Prefetch) {
+  // Arrange
+  NewTabPageAdInfo expected_ad = BuildNewTabPageAd();
+  EXPECT_CALL(*ads_service_, MaybeServeNewTabPageAd(::testing::_))
+      .WillOnce(::testing::Invoke(
