+void CheckAPI(kvs_result ret)
+{
+    if (ret != KVS_SUCCESS)
+    {
+        // printf("kvssd error (errmsg: %s)\n", kvstrerror[ret]);
+        throw Exception(std::string(kvstrerror[ret]));
+    }
+    printf("%s\n", kvstrerror[ret]);
+}
