+}
+
+TEST_F(LoadedPluginTestFixture, NoLoadedPluginsTest) {
+  EXPECT_TRUE(HasOnlyLoadedPlugins());
+}
+
+TEST_F(LoadedPluginTestFixture, LoadSinglePluginTest) {
