+    };
+
+    fn len(&self) -> usize {
+        const MAX_ITEMS: usize = 32;
+        MAX_ITEMS
+    }
+
+    fn total_size(&self) -> usize {
+        self.total_item_size() +
+            core::mem::size_of::<u64>() /* idx */ +
+            core::mem::size_of::<bool>() /* is_empty */
+    }
+}
+
