+  /** Creates a new instance of the LargeFirstSelector. */
+  constructor(props: LargeFirstSelectorProps) {
+    this.#props = props;
+  }
+
+  /**
+   * Selects inputs using a large-first strategy:
+   * Selects largest UTXOs per asset until target is met
