+    let workingUtxo = new Set<Cardano.Utxo>(preSelected);
+    workingUtxo = this.#selectAssets(outputAssets, allAvailable, [...workingUtxo]);
+    workingUtxo = this.#selectLovelace(
+      totalLovelaceOutput,
+      allAvailable,
+      workingUtxo,
+      implicitValue?.coin?.input ?? 0n
+    );
