+    const { finalSelection, fee, change } = await this.#expandUtxosUntilFeeCovered(
+      workingUtxo,
+      outputs,
+      allAvailable,
+      outputAssets,
+      constraints,
+      this.#props.changeAddressResolver,
+      implicitValue
+    );
