+#### Function call executed automatically
+
+In addition to the manual function calls, SDK supports automatic function calling.  Here is the example:
+
+Here we use other functions for demonstration:
+```C# Snippet:StreamingWithAutoFunctionCall_DefineFunctions
+private class Address
+{
+    public string Street { get; set; }
+    public string City { get; set; }
+}
+
+private int GetHumidityByAddress(Address address)
+{
+    return (address.City == "Seattle") ? 60 : 80;
+}
+
+private string[] GetWeatherByAddresses(Dictionary<string, string>[] addresses, string unit = "F")
+{
+    string[] temps = new string[addresses.Length];
+    for (int i = 0; i < addresses.Length; i++)
+    {
+        if (addresses[i].TryGetValue("city", out string city))
+        {
+            temps[i] = string.Format("{0}{1}", (city == "Seattle") ? "20" : "50", unit);
+        }
+        else
+        {
+            throw new ArgumentException("Each address must contain 'street' and 'city' keys.");
+        }
+    }
+    return temps;
+}
+```
+Now we define the function definitions:
+```C# Snippet:StreamingWithAutoFunctionCall_DefineFunctionTools
+private FunctionToolDefinition geHhumidityByAddressTool = new(
+     name: "GetHumidityByAddress",
+     description: "Get humidity by street and city",
+     parameters: BinaryData.FromObjectAsJson(
+     new
+     {
+         Type = "object",
+         Properties = new
+         {
+             Address = new
+             {
+                 Type = "object",
+                 Properties = new
+                 {
+                     Street = new
+                     {
+                         Type = "string",
+                         Description = "Street"
+                     },
+                     City = new
+                     {
+                         Type = "string",
+                         Description = "city"
+                     },
+                 },
+                 Required = new[] { "street", "city" }
+             }
+         },
+         Required = new[] { "address" }
+     },
+     new JsonSerializerOptions() { PropertyNamingPolicy = JsonNamingPolicy.CamelCase }));
+
+private FunctionToolDefinition getWeatherByAddressesTool = new(
+     name: "GetWeatherByAddresses",
+     description: "Get weather by street and city",
+     parameters: BinaryData.FromObjectAsJson(
+     new
+     {
+         Type = "object",
+         Properties = new
+         {
+             Addresses = new
+             {
+                 Type = "array",
+                 Description = "A list of addresses",
+                 Items = new
+                 {
+                     Type = "object",
+                     Properties = new
+                     {
+                         Street = new
+                         {
+                             Type = "string",
+                             Description = "Street"
+                         },
+                         City = new
+                         {
+                             Type = "string",
+                             description = "city"
+                         },
+                     },
+                     Required = new[] { "street", "city" }
+                 }
+             },
+             Unit = new
+             {
+                 Type = "string",
+                 Enum = new[] { "c", "f" },
+             },
+         },
+         Required = new[] { "addresses" }
+     },
+     new JsonSerializerOptions() { PropertyNamingPolicy = JsonNamingPolicy.CamelCase }));
+```
+Use `EnableAutoFunctionCall` to enable the auto function call:
+```C# Snippet:StreamingWithAutoFunctionCall_EnableAutoFunctionCalls
+List<ToolOutput> toolOutputs = new();
+Dictionary<string, Delegate> delegates = new();
+delegates.Add(nameof(GetWeatherByAddresses), GetWeatherByAddresses);
+delegates.Add(nameof(GetHumidityByAddress), GetHumidityByAddress);
+AIProjectClientOptions options = new();
+options.EnableAutoFunctionCalls(delegates);
+
+AgentsClient client = new(connectionString, new DefaultAzureCredential(), options);
+```
+
+
+When you create an agent, you can specify the function call by tools argument similar to the example of manual function calls:
+```C# Snippet:StreamingWithAutoFunctionCall_CreateAgent
+Agent agent = client.CreateAgent(
+    model: modelDeploymentName,
+    name: "SDK Test Agent - Functions",
+        instructions: "You are a weather bot. Use the provided functions to help answer questions. "
+            + "Customize your responses to the user's preferences as much as possible and use friendly "
+            + "nicknames for cities whenever possible.",
+    tools: [getWeatherByAddressesTool, geHhumidityByAddressTool]
+);
+```
+
+We create a thread and message similar to the example of manual function tool calls:
+```C# Snippet:StreamingWithAutoFunctionCall_CreateThreadMessage
+AgentThread thread = client.CreateThread();
+
+ThreadMessage message = client.CreateMessage(
+    thread.Id,
+    MessageRole.User,
+    "Get weather and humidity for street, 123 1st St in city, Seattle and street, 456 2nd Ave in city, Bellevue");
+```
+
+The agent will then call the function automatically when it is needed during `CreateRunStreamingAsync`:

