+  // Act
+  prefetcher_->Prefetch();
+  std::optional<NewTabPageAdInfo> result = prefetcher_->MaybeGetPrefetchedAd();
+
+  // Assert
+  ASSERT_TRUE(result.has_value());
+  EXPECT_EQ(*result, expected_ad);
+}
+
+TEST_F(BraveAdsNewTabPageAdPrefetcherTest, PrefetchFailed) {
+  // Arrange
+  EXPECT_CALL(*ads_service_, MaybeServeNewTabPageAd(::testing::_))
+      .WillOnce(::testing::Invoke([](MaybeServeNewTabPageAdCallback callback) {
+        std::move(callback).Run(std::nullopt);
+      }));
+
+  // Act
+  prefetcher_->Prefetch();
+  std::optional<NewTabPageAdInfo> result = prefetcher_->MaybeGetPrefetchedAd();
+
+  // Assert
+  EXPECT_FALSE(result.has_value());

