+    const safeSortBy = allowedSortFields.includes(sortBy) ? sortBy : 'goods_id';
+    const safeOrder = allowedOrders.includes(order) ? order : 'asc';
+
+    const query = `
+      SELECT * FROM supplier
+      ORDER BY ${safeSortBy} ${safeOrder}
+    `;

