+    const { publication, columnsToShow, editAction, deleteAction, disabled } = props;
+
+    const [showDeleteModal, setShowDeleteModal] = useState(false);
+
+    const disabledStyle = {
+        cursor: 'not-allowed',
+        opacity: 0.5
+    };
