+                    <span style={{ marginLeft: '1rem' }}></span>
+                </a>
+            </div>
+            {/* delete button */}
+            <a
+                style={{ marginLeft: 10, ...buttonStyle }}
+                onClick={() => !disabled && setShowDeleteModal(true) }
+            >
+                <span
+                    className='glyphicon glyphicon-trash publication-delete-icon'
