+    <FocusTrap
+      focusTrapOptions={{
+        onDeactivate: closeDropdown,
+        clickOutsideDeactivates: true,
+      }}
+    >
+      <div
+        className={moduleStyles.settingsDropdown}
+        ref={dropdownRef}
+        role="dialog"
+        style={dropdownStyles}
+        aria-modal="true"
+        aria-label={commonI18n.settings()}
+      >
