+        }
+        checkNotNull(deserializationSchema, "Deserialization schema is required but not provided.");
+
+        checkNotNull(
+                scanPartitionDiscoveryIntervalMs,
+                "ScanPartitionDiscoveryIntervalMs is required but not provided.");

