+// Debug Housekeeping monitor
+
+class CSashaDebugPlaneHousekeepingServer : public ISashaServer, public Thread
+{
+    std::atomic<bool> stopped{true};
+    Semaphore stopSem;
+    Mutex runMutex;
+    StringBuffer debugDir;
