+  }
+
+  @Override
+  public void close() throws IOException {
+    try {
+      if (taskSharedCount != null) {
+        taskSharedCount.close();
+      }
+
+      if (recoverySharedCount != null) {
+        recoverySharedCount.close();
+      }
+    } finally {
+      if (client != null) {
+        client.close();
+      }
+    }
+  }
+
