+            primitiveToWrapper.put("boolean", "java.lang.Boolean");
+            primitiveToWrapper.put("byte", "java.lang.Byte");
+            primitiveToWrapper.put("short", "java.lang.Short");
+            primitiveToWrapper.put("char", "java.lang.Character");
