+package org.openrewrite.java.dropwizard.method;
+
+import org.jspecify.annotations.Nullable;
+import org.openrewrite.ExecutionContext;
+import org.openrewrite.Recipe;
+import org.openrewrite.java.JavaIsoVisitor;
+import org.openrewrite.java.tree.J;
+import org.openrewrite.java.tree.JavaType;
+import org.openrewrite.java.tree.TypeUtils;
+
+public class RemoveUnnecessarySuperCalls extends Recipe {
+
+
+    @Override
+    public String getDisplayName() {
+        return "Remove `super` calls when the class does not extend another class";
+    }
+
+    @Override
+    public String getDescription() {
+        return "Removes calls to `super(...)` or `super.someMethod(...)` if the class does not have a real superclass besides `java.lang.Object`.";
+    }
+
+    @Override
+    public JavaIsoVisitor<ExecutionContext> getVisitor() {
+        return new RemoveUnnecessarySuperCallsVisitor();
+    }
+
+    public static class RemoveUnnecessarySuperCallsVisitor extends JavaIsoVisitor<ExecutionContext> {
+        private static final String SUPER = "super";
+
+        @Override
+        public J.@Nullable MethodInvocation visitMethodInvocation(
+                J.MethodInvocation method, ExecutionContext ctx) {
+            J.MethodInvocation mi = super.visitMethodInvocation(method, ctx);
+
+            if (isSuperCall(mi)) {
+                J.ClassDeclaration classDecl = getCursor().firstEnclosing(J.ClassDeclaration.class);
+                if (classDecl != null) {
+                    boolean hasRealParent = hasRealSuperclass(classDecl);
+
+                    if (!hasRealParent) {
