+    body: data,
+    headers: {
+      'Content-Type': 'application/json',
+      ...authHeaders,
+      ...headers,
+    },
+    query: {
+      format: 'json',
+      ...query,
+    },
+    maxRedirections,
+    parseAs,
+    baseUrl,
+  };
+
+  return commonRequest(method, requestPath, options).then(logResponse);
